function normalizarNombre(texto) {
  return String(texto || '')
    .trim()
    .toLocaleLowerCase('es')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function limpiarTextoCorreo(texto) {
  return String(texto || '')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/(?:p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\r\n?/g, '\n');
}

class Producto {
  constructor(id, nombre, stock, precio) {
    this.id = id;
    this.nombre = nombre;
    this.stock = stock;
    this.precio = precio;
  }

  tieneStock(cantidad) {
    return Number.isSafeInteger(cantidad) && cantidad > 0 &&
      Number.isFinite(this.stock) && this.stock >= cantidad;
  }

  calcularTotal(cantidad) {
    if (!Number.isSafeInteger(cantidad) || cantidad <= 0) {
      throw new RangeError('La cantidad debe ser un entero positivo.');
    }
    return this.precio * cantidad;
  }
}

class SolicitudCotizacion {
  constructor(remitente, textoCorreo) {
    this.remitente = remitente;
    this.textoCorreo = textoCorreo;
  }

  extraerDatos() {
    const texto = limpiarTextoCorreo(this.textoCorreo);
    const coincidenciaProducto = texto.match(
      /producto\s*:\s*([^\r\n/]+)/i
    );
    const coincidenciaCantidad = texto.match(
      /cantidad\s*:\s*(\d+)(?![\d.,]\d)\s*(?:unidad(?:es)?|uds?\.?)?(?=\s*(?:$|[\r\n.,;]))/i
    );

    if (!coincidenciaProducto || !coincidenciaCantidad) {
      return { producto: '', cantidad: null };
    }

    const producto = normalizarNombre(
      coincidenciaProducto[1].replace(/\s+/g, ' ')
    );
    const cantidad = Number(coincidenciaCantidad[1]);

    return {
      producto,
      cantidad: Number.isSafeInteger(cantidad) ? cantidad : null
    };
  }

  esValida() {
    const { producto, cantidad } = this.extraerDatos();
    return producto.length > 0 &&
      Number.isSafeInteger(cantidad) &&
      cantidad > 0;
  }

  determinarEstado(producto, servicioError = null) {
    if (!this.esValida()) {
      return {
        estado: 'rechazada',
        motivo: 'El correo está incompleto o la cantidad no es un entero positivo.'
      };
    }

    if (servicioError) {
      return {
        estado: 'rechazada',
        motivo: 'No se pudo consultar el inventario: ' + String(servicioError)
      };
    }

    if (producto === null || producto === undefined) {
      return {
        estado: 'rechazada',
        motivo: 'El producto solicitado no existe en el catálogo.'
      };
    }

    const { cantidad } = this.extraerDatos();
    if (producto.tieneStock(cantidad)) {
      return {
        estado: 'pendiente',
        motivo: 'Hay stock suficiente para ' + cantidad + ' unidad(es).'
      };
    }

    return {
      estado: 'sin stock',
      motivo: 'Stock insuficiente para ' + cantidad + ' unidad(es).'
    };
  }
}


function obtenerRemitente(valor) {
  if (typeof valor === 'string') return valor;
  if (valor && Array.isArray(valor.value) && valor.value[0]) {
    return valor.value[0].address || valor.value[0].name || '';
  }
  if (valor && typeof valor.text === 'string') return valor.text;
  return '';
}

const correo = $json;
const textoCorreo = correo.textPlain || correo.textHtml || correo.text ||
  correo.body || correo.html || correo.raw || '';
const remitente = obtenerRemitente(correo.from || correo.From || correo.sender);
const asunto = correo.subject || correo.Subject || '';
const solicitud = new SolicitudCotizacion(remitente, textoCorreo);
const datos = solicitud.extraerDatos();
const textoCompleto = asunto + '\n' + textoCorreo;
const mencionaCotizacion = /\b(cotizaci[oó]n(?:es)?|cotizar|cotice|presupuesto|quote|quotation)\b/i.test(textoCompleto);
const solicitaCotizacion = /\b(solicitud|solicito|solicitar|necesito|quisiera|requiero|deseo|cotizar|cotice|presupuesto|quote|quotation)\b/i.test(textoCompleto);
const tieneCampos = /\bproducto\s*:/i.test(textoCompleto) && /\bcantidad\s*:/i.test(textoCompleto);
const esCandidatoCotizacion = tieneCampos || (mencionaCotizacion && solicitaCotizacion);

return {
  json: {
    remitente,
    asunto,
    textoCorreo: String(textoCorreo),
    esCandidatoCotizacion,
    messageId: correo.id || correo.messageId || null,
    productoSolicitado: datos.producto,
    cantidad: datos.cantidad,
    valida: solicitud.esValida()
  }
};

