      '',
      'Gracias por su solicitud. En este momento no contamos con existencias suficientes para atender la cantidad solicitada.',
      '',
      'Producto: ' + producto,
      'Cantidad solicitada: ' + cantidad + ' unidad(es)',
      'Disponibilidad registrada: ' + disponible + ' unidad(es)',
      '',
      'Si desea, puede responder este correo para consultar una alternativa o confirmar si le interesa la cantidad disponible.',
      '',
      'Saludos cordiales,',
      'Equipo de Cotizaciones',
      'Soluciones Negocio'
    ].join('\n');
  } else if (solicitud.motivo && solicitud.motivo.toLowerCase().includes('no existe en el catálogo')) {
    cuerpoRespuesta = [
      'Buenos días:',
      '',
      'Gracias por contactarnos. No encontramos “' + producto + '” en nuestro catálogo actual.',
      '¿Podría confirmar el nombre o modelo del producto para revisar su solicitud?',
      '',
      'Quedamos atentos.',
      '',
      'Saludos cordiales,',
      'Equipo de Cotizaciones',
      'Soluciones Negocio'
    ].join('\n');
  } else if (solicitud.motivo && solicitud.motivo.toLowerCase().includes('consultar el inventario')) {
    cuerpoRespuesta = [
      'Buenos días:',
      '',
      'Recibimos su solicitud, pero en este momento no fue posible consultar el inventario. Le agradecemos intentarlo nuevamente más tarde.',
      '',
      'Saludos cordiales,',
      'Equipo de Cotizaciones',
      'Soluciones Negocio'
    ].join('\n');
  } else {
    cuerpoRespuesta = [
      'Buenos días:',
      '',
      'Gracias por contactarnos. No logramos identificar el producto y la cantidad de su solicitud.',
      'Por favor, responda este correo con los siguientes datos en líneas separadas:',
      '',
      'Producto: Laptop',
      'Cantidad: 2 unidades',
      '',
      'Quedamos atentos para continuar con la cotización.',
      '',
      'Saludos cordiales,',
      'Equipo de Cotizaciones'
    ].join('\n');
  }

  return { asuntoRespuesta, cuerpoRespuesta };
}

